mapper.select:
select
id,
project_id,
object_id,
info_code,
type
from cache_rule
where project_id = #{projectId}
and
(


    (
    object_id = #{businessKey.objectId}
    and info_code = #{businessKey.infoCode}
    and type = #{businessKey.type}
    )

)
order by id

select id, project_id, object_id, info_code, type from cache_rule where project_id = #{projectId} and type = #{type} and object_id in
#{objectId}
and info_code in
#{infoCode}
order by object_id, info_code, id

mapper.delete:
delete from cache_rule where project_id = #{projectId} and id in
#{ruleId}
and not exists ( select 1 from cache_rule_key_rel relation where relation.project_id = cache_rule.project_id and relation.rule_id = cache_rule.id )
